// assets-manifest.json (generated by tools/build-asset-manifest.ps1) must describe the tree exactly:
// it is what a published tag is verified against byte-for-byte.
import { test, expect } from '@playwright/test';
import { listAssets, readAsset, sha256, loadManifest } from '../../lib/walk.mjs';

const manifest = loadManifest();

test.describe('assets-manifest.json', () => {
  test('exists and is well formed', () => {
    expect(manifest, 'BLOCKED: assets-manifest.json has not been generated — run tools/build-asset-manifest.ps1').not.toBeNull();
    expect(Array.isArray(manifest.files)).toBe(true);
    expect(manifest.count).toBe(manifest.files.length);
    expect(manifest.totalBytes).toBe(manifest.files.reduce((n, f) => n + f.bytes, 0));
    for (const f of manifest.files) {
      expect(f.path, 'manifest paths are posix, repo-relative').toMatch(/^[^\\]+$/);
      expect(f.sha256).toMatch(/^[0-9a-f]{64}$/);
      expect(Number.isInteger(f.bytes) && f.bytes > 0).toBe(true);
    }
  });

  test('lists exactly the files on disk (no missing, no extra)', () => {
    test.skip(!manifest, 'manifest missing — see the first test');
    const disk = new Set(listAssets());
    const listed = new Set(manifest.files.map((f) => f.path));
    expect([...disk].filter((p) => !listed.has(p)), 'on disk but not in manifest — regenerate it').toEqual([]);
    expect([...listed].filter((p) => !disk.has(p)), 'in manifest but not on disk — regenerate it').toEqual([]);
  });

  test('byte size and SHA-256 of every file match the manifest', () => {
    test.skip(!manifest, 'manifest missing — see the first test');
    const diffs = [];
    for (const f of manifest.files) {
      let buf; try { buf = readAsset(f.path); } catch { continue; } // missing files are reported by the previous test
      if (buf.length !== f.bytes) diffs.push(`${f.path}: ${buf.length} bytes on disk, manifest says ${f.bytes}`);
      else if (sha256(buf) !== f.sha256) diffs.push(`${f.path}: content changed since the manifest was generated`);
    }
    expect(diffs).toEqual([]);
  });

  test('no duplicate paths and no byte-identical duplicate files (MAU-LAW-5: never copy an asset twice)', () => {
    test.skip(!manifest, 'manifest missing — see the first test');
    const paths = manifest.files.map((f) => f.path);
    expect(new Set(paths).size).toBe(paths.length);
    const byHash = new Map();
    for (const f of manifest.files) {
      if (f.bytes < 4096) continue; // tiny icons legitimately coincide
      byHash.set(f.sha256, [...(byHash.get(f.sha256) ?? []), f.path]);
    }
    const dups = [...byHash.values()].filter((v) => v.length > 1);
    expect(dups, 'identical files stored twice').toEqual([]);
  });
});
